"""Evidence-trail audit: list every number written literally in the manuscript (not generated by a macro).

Numbers produced by \\newcommand macros come from scripts/export_paper_numbers.py and are traceable by
construction. Literal numbers must each be traced by hand to a result file, the source study or a
reference; this script lists them with context so none is missed.

Usage: python scripts/audit_manuscript_numbers.py manuscript/main.tex
"""
import re
import sys
from pathlib import Path

tex = Path(sys.argv[1]).read_text(encoding="utf-8")
body = tex[tex.index("\\begin{document}"):tex.index("\\begin{thebibliography}")]
body = re.sub(r"%.*", "", body)                                   # comments
body = re.sub(r"\\(label|ref|cite|includegraphics|url|path)\{[^}]*\}", " ", body)
body = re.sub(r"\\begin\{tabular[x]?\}.*?\\end\{tabular[x]?\}", " ", body, flags=re.S)  # tables use macros
hits = []
for m in re.finditer(r"(?<![\\A-Za-z])(\d+(?:[.,]\d+)?(?:--\d+(?:\.\d+)?)?\s?(?:\\%|%|nm|h)?)", body):
    tok = m.group(1).strip()
    ctx = body[max(0, m.start() - 60): m.end() + 40].replace("\n", " ")
    if re.fullmatch(r"\d", tok):        # single digits (section words, counts like "three") skipped below
        continue
    hits.append((tok, ctx))
seen = set()
for tok, ctx in hits:
    key = (tok, ctx[:40])
    if key in seen:
        continue
    seen.add(key)
    print(f"{tok:>14} | ...{ctx}...")
print(f"\n{len(seen)} literal numbers (excluding single digits) to trace")
